			Labels: nvcatypes.GetLabelsForRequest(&nvcav2beta1.ICMSRequest{
				ObjectMeta: metav1.ObjectMeta{
					Name: "test-req",
				},
				Spec: nvcav2beta1.ICMSRequestSpec{
